<?php if(!$invitations->canSend())return;
$printState=($calendarRecipientState['kind']??'')==='print'?$calendarRecipientState:[];$printContext=$printState||in_array(input($_POST,'action'),['preview-event-print','create-event-print'],true);$printPost=$printContext?$_POST:[];
$printGroups=$printContext?arrayInput($printPost,'groups'):[($event['activity_kind']??'')==='board'?'board':'members'];$printPeople=arrayInput($printPost,'recipients');
$printService=new \Kulturhus\Verein\CalendarPrints($db,(string)$_SESSION['actor'],$invitations); ?>
<div class="content"><details class="card" <?= $printContext?'open':'' ?>><summary><?= e($calendarText('Einladungsbriefe / Sammeldruck')) ?></summary><p><?= e($calendarText('Ein persönlicher Brief pro ausgewählter Person. Für Duplexdruck beginnt jede Einladung auf einem neuen Blatt. Fehlende Anschriften werden ausgewiesen. Ein erzeugtes PDF bedeutet noch keinen Postversand.')) ?></p><form method="post" data-calendar-recipient-form="print"><?= csrf().hidden('action','preview-event-print').hidden('id',$event['id']) ?><label><?= e($calendarText('Empfängergruppe')) ?><select class="form-control" name="groups[]"><?php foreach($invitations->groupsFor($event['id']) as $k=>$v): ?><option value="<?= $k ?>" <?= in_array($k,$printGroups,true)?'selected':'' ?>><?= e($calendarText($v)) ?></option><?php endforeach ?></select></label><details <?= $printState||in_array('selected',$printGroups,true)?'open':'' ?>><summary><?= e($calendarText('Einzelne Personen auswählen')) ?></summary><?= \Kulturhus\Verein\CalendarRecipientPicker::render($invitations,$event['id'],'print',$printPeople,$printState,$calendarText) ?></details><label><?= e($calendarText('Postauswahl')) ?><select class="form-control" name="print_mode"><option value="missing"><?= e($calendarText('Nur ohne eigene oder Familien-Mailadresse')) ?></option><option value="all" <?= input($printPost,'print_mode')==='all'?'selected':'' ?>><?= e($calendarText('Alle ausgewählten Personen')) ?></option></select></label><label><?= e($calendarText('Betreff')) ?><input class="form-control" name="subject" maxlength="200" required value="<?= e(input($printPost,'subject','Einladung: '.$event['title'])) ?>"></label><label><?= e($calendarText('Nachricht')) ?><textarea class="form-control" name="message" maxlength="10000" rows="4"><?= e(input($printPost,'message')) ?></textarea></label><p><?= e($calendarText('Datum, Ort und gespeicherte Tagesordnung werden ergänzt. Einladungsfrist und Versandform anhand eurer Satzung prüfen.')) ?></p><button class="btn btn-solid theme-primary"><?= e($calendarText('Briefe prüfen')) ?></button></form>
<?php if($printPreview??null): ?><h3><?= e($calendarFormat('{count} Briefe',['count'=>count($printPreview['recipients'])])) ?></h3><p><?= nl2br(e($printPreview['invitation']['body'])) ?></p><details><summary><?= e($calendarText('Empfängeranschriften anzeigen')) ?></summary><ul><?php foreach($printPreview['recipients'] as $p): ?><li><?= e($p['name']) ?> · <?= nl2br(e($p['address'])) ?></li><?php endforeach ?></ul></details><?php if($printPreview['missing']): ?><details><summary><?= e($calendarFormat('Ohne Anschrift: {count}',['count'=>count($printPreview['missing'])])) ?></summary><p><?= e(implode(', ',$printPreview['missing'])) ?></p></details><?php endif ?><form method="post"><?= csrf().hidden('action','create-event-print').hidden('id',$event['id']).hidden('subject',input($printPost,'subject')).hidden('message',input($printPost,'message')).hidden('print_mode',input($printPost,'print_mode')).hidden('preview_hash',$printPreview['hash']).hidden('request_key',bin2hex(random_bytes(16))) ?><?php foreach($printGroups as $g)echo hidden('groups[]',$g);echo \Kulturhus\Verein\CalendarRecipientPicker::confirmation($printPeople); ?><button class="btn btn-solid theme-primary" <?= !$printPreview['recipients']?'disabled':'' ?>><?= e($calendarText('Geprüften Sammeldruck erstellen')) ?></button></form><?php endif ?>
<?php foreach($printService->listing($event['id']) as $batch): ?><p><a href="<?= e(url(['calendar_print'=>$batch['id']])) ?>"><?= e($calendarFormat('Sammeldruck vom {date} herunterladen',['date'=>$batch['created_at']])) ?></a> · <?= e($calendarFormat('Postaufgabe: {state}',['state'=>$batch['posted_at']?:$calendarText('Noch keine Postaufgabe vermerkt')])) ?></p><?php if(!$batch['posted_at']): ?><form method="post"><?= csrf().hidden('action','posted-event-print').hidden('id',$batch['id']).hidden('event_id',$event['id']) ?><button class="btn btn-outline theme-secondary secondary"><?= e($calendarText('Tatsächliche Postaufgabe vermerken')) ?></button></form><?php endif;endforeach ?></details></div>
